import csv
import io


def _is_number(value):
    try:
        float(value.strip())
    except ValueError:
        return False
    return True


def _is_grouped_header(groups, labels, width):
    if len(groups) != width or len(labels) != width:
        return False

    groups = [value.strip() for value in groups]
    labels = [value.strip() for value in labels]
    return (
        bool(groups[0])
        and any(not value for value in groups)
        and all(not _is_number(value) for value in groups if value)
        and all(value and not _is_number(value) for value in labels)
    )


def parse_csv(raw_csv: str):
    expected_width = 4
    records = list(csv.reader(
        io.StringIO(raw_csv.removeprefix("\ufeff"), newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    start = 0
    while start < len(records) and not records[start]:
        start += 1
    if start == len(records):
        return {"columns": [], "rows": []}

    # Skip short textual preamble records only if a grouped header follows.
    candidate = start
    while candidate < len(records):
        row = records[candidate]
        if len(row) >= expected_width or any(_is_number(value) for value in row):
            break
        candidate += 1

    if candidate + 1 < len(records) and _is_grouped_header(
        records[candidate], records[candidate + 1], expected_width
    ):
        names = []
        group = ""
        for parent, child in zip(records[candidate], records[candidate + 1]):
            if parent.strip():
                group = parent.strip()
            names.append(f"{group} / {child.strip()}")
        rows = records[candidate + 2:]
    else:
        names = list(records[start])
        rows = records[start + 1:]

    width = max(expected_width, len(names), max(map(len, rows), default=0))
    reserved = {name for name in names if name.strip()}
    used = set()
    columns = []
    for index in range(width):
        name = names[index] if index < len(names) else ""
        if not name.strip() or name in used:
            base = name if name.strip() else f"column_{index + 1}"
            name = base
            suffix = 2
            while name in reserved or name in used:
                name = f"{base}_{suffix}"
                suffix += 1
        columns.append(name)
        used.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
